"""Research-only semantic duplicate groups; never edits the question bank."""
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
x=json.loads((ROOT/'data/duplicate-candidates-DGT302.json').read_text(encoding='utf-8'))
by={q['id']:q for q in x['questions']}
groups=[];used=set()
def norm(s):
 s=unicodedata.normalize('NFKC',s).casefold().replace('−','-').replace('–','-').replace('·','*')
 return re.sub(r'[^\wπ]+','',s)
def add(nums,reason):
 ids=[f'DGT302-{n}' for n in nums]
 assert not used.intersection(ids),(ids,used.intersection(ids));used.update(ids)
 canonical=by[ids[0]];maps={}
 for id in ids[1:]:
  q=by[id];m=[]
  for o in q['options']:
   hits=[i for i,c in enumerate(canonical['options']) if norm(o)==norm(c)]
   m.append(hits[0] if len(hits)==1 else None)
  maps[id]=m
 exact=all(norm(by[id]['question'])==norm(canonical['question']) and all(i is not None for i in maps[id]) and len(set(maps[id]))==len(canonical['options']) for id in ids[1:])
 groups.append({'ids':ids,'reasonVi':reason,'kind':'exact' if exact else 'reworded','optionMaps':maps})

